/**
 * Full unit suite for the pure-JS search plugin: glob compiler, walker,
 * grep semantics, output retention/render and workspace containment.
 *
 * Containment-focused cases live in ./contain.test.mjs; this file keeps the
 * broader semantic surface pinned (mtime ordering, VCS skipping, binary
 * detection, CR stripping, cap footers, UTF-8-safe truncation).
 *
 * Run from the payload root so `@deepseek-ai/*` imports resolve:
 *   node --test host/.../dsh-tool-fs-search-js/test/fs-search.test.mjs
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdirSync, mkdtempSync, writeFileSync, utimesSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import {
  compileGlobPattern, compileContentPattern, expandBraces, previewLine,
  runGlob, runGrep, retainGrepMatches, formatRetainedGrep, formatGlobPage,
  formatGrepMatches, parseGlobArgs, parseGrepArgs, toWorkdirRelative, SearchError
} from '../index.js'

const CAPS = {
  globMaxResults: 100,
  grepMaxMatches: 250,
  grepMaxLineBytes: 2000,
  maxFileBytes: 20 * 1024 * 1024,
  rawOutputMaxBytes: 2e7,
  timeoutMs: 30000
}

/**
 * Deterministic tree (mtimes: old.txt oldest ... c.ts newest):
 *   old.txt(400) .hidden.log(350) a.ts(300) binary.dat(250) readme.md(200)
 *   src/deep/nested/d.js(150) src/b.ts(100) node_modules/x/index.js(50)
 *   src/deep/c.ts(10)   plus .git/HEAD (excluded) and sub/sibling material
 */
function fixture() {
  const ws = mkdtempSync(join(tmpdir(), 'dsh-fssearch-'))
  mkdirSync(join(ws, 'src', 'deep', 'nested'), { recursive: true })
  mkdirSync(join(ws, '.git'), { recursive: true })
  mkdirSync(join(ws, 'node_modules', 'x'), { recursive: true })
  mkdirSync(join(ws, 'sub'), { recursive: true })
  writeFileSync(join(ws, 'readme.md'), '# hello\r\nworld\r\n')
  writeFileSync(join(ws, 'old.txt'), 'old file\n')
  writeFileSync(join(ws, 'a.ts'), 'export const a = 1\n// TODO: fix\n')
  writeFileSync(join(ws, 'src', 'b.ts'), 'export const b = 2\n')
  writeFileSync(join(ws, 'src', 'deep', 'c.ts'), 'export const c = 3\n')
  writeFileSync(join(ws, 'src', 'deep', 'nested', 'd.js'), 'const d = 4\n')
  writeFileSync(join(ws, 'binary.dat'), Buffer.from([0x00, 0x01, 0x02, 0x41]))
  writeFileSync(join(ws, '.hidden.log'), 'secret TODO\n')
  writeFileSync(join(ws, '.git', 'HEAD'), 'ref: refs/heads/main\n')
  writeFileSync(join(ws, 'node_modules', 'x', 'index.js'), 'TODO in node_modules\n')
  writeFileSync(join(ws, 'sub', 'a.txt'), 'TODO inside\n')
  const T = (d) => new Date(Date.now() - d * 1000)
  utimesSync(join(ws, 'sub', 'a.txt'), T(5), T(5))
  utimesSync(join(ws, 'old.txt'), T(400), T(400))
  utimesSync(join(ws, '.hidden.log'), T(350), T(350))
  utimesSync(join(ws, 'a.ts'), T(300), T(300))
  utimesSync(join(ws, 'binary.dat'), T(250), T(250))
  utimesSync(join(ws, 'readme.md'), T(200), T(200))
  utimesSync(join(ws, 'src', 'deep', 'nested', 'd.js'), T(150), T(150))
  utimesSync(join(ws, 'src', 'b.ts'), T(100), T(100))
  utimesSync(join(ws, 'node_modules', 'x', 'index.js'), T(50), T(50))
  utimesSync(join(ws, 'src', 'deep', 'c.ts'), T(10), T(10))
  utimesSync(join(ws, '.git', 'HEAD'), T(30), T(30))
  const ctx = { workingDirectory: { ensure: async () => ws } }
  const exec = { agent: {}, signal: new AbortController().signal }
  return { ws, ctx, exec }
}

// ---------- glob pattern compiler ----------

test('compiler: bare pattern matches basename at any depth', () => {
  assert.equal(compileGlobPattern('*.ts').test('a.ts'), true)
  assert.equal(compileGlobPattern('*.ts').test('src/deep/c.ts'), true)
  assert.equal(compileGlobPattern('*.ts').test('d.js'), false)
})

test('compiler: bare pattern rejects dir-like traversal', () => {
  assert.equal(compileGlobPattern('*.ts').test('a.ts/x'), false)
})

test('compiler: slash-anchored pattern stays under prefix', () => {
  assert.equal(compileGlobPattern('src/**/*.ts').test('src/b.ts'), true)
  assert.equal(compileGlobPattern('src/**/*.ts').test('src/deep/c.ts'), true)
  assert.equal(compileGlobPattern('src/**/*.ts').test('a.ts'), false)
})

test('compiler: * matches everything', () => {
  assert.equal(compileGlobPattern('*').test('src/deep/c.ts'), true)
})

test('compiler: brace alternation expands', () => {
  assert.deepEqual(expandBraces('{a,b}.ts'), ['a.ts', 'b.ts'])
  assert.equal(compileGlobPattern('{a,b}.ts').test('a.ts'), true)
  assert.equal(compileGlobPattern('{a,b}.ts').test('src/b.ts'), true)
})

test('compiler: ? matches exactly one char', () => {
  assert.equal(compileGlobPattern('?.ts').test('a.ts'), true)
  assert.equal(compileGlobPattern('?.ts').test('ab.ts'), false)
})

test('compiler: **/*.js reaches nested files', () => {
  assert.equal(compileGlobPattern('**/*.js').test('src/deep/nested/d.js'), true)
})

// ---------- runGlob ----------

test('glob: finds files by extension, skips .git', async () => {
  const { ctx, exec } = fixture()
  const { paths } = await runGlob(ctx, CAPS, { pattern: '*.ts' }, exec)
  assert.equal(paths.length, 3)
  assert.equal(paths.some((p) => p.includes('.git')), false)
})

test('glob: includes hidden and node_modules (rg --hidden --no-ignore parity)', async () => {
  const { ctx, exec } = fixture()
  assert.equal((await runGlob(ctx, CAPS, { pattern: '.hidden.log' }, exec)).paths.length, 1)
  assert.equal((await runGlob(ctx, CAPS, { pattern: 'node_modules/**/*.js' }, exec)).paths.length, 1)
})

test('glob: mtime ascending, old.txt first and newest last', async () => {
  const { ctx, exec } = fixture()
  const { paths } = await runGlob(ctx, CAPS, { pattern: '**' }, exec)
  assert.equal(paths[0], 'old.txt')
  assert.equal(paths[paths.length - 1], 'sub/a.txt')
})

test('glob: default root is the workdir', async () => {
  const { ctx, exec } = fixture()
  const { root } = await runGlob(ctx, CAPS, { pattern: '*.ts' }, exec)
  assert.equal(root, '.')
})

test('glob: path arg prefixes output and sets root', async () => {
  const { ctx, exec } = fixture()
  const result = await runGlob(ctx, CAPS, { pattern: '*.ts', path: 'src' }, exec)
  assert.equal(result.paths.length, 2)
  assert.ok(result.paths.every((p) => p.startsWith('src/')))
  assert.equal(result.root, 'src')
})

test('glob: no match yields empty paths', async () => {
  const { ctx, exec } = fixture()
  const { paths } = await runGlob(ctx, CAPS, { pattern: 'nonexistent-*.xyz' }, exec)
  assert.equal(paths.length, 0)
})

test('glob: missing path fails with SEARCH_FAILED', async () => {
  const { ctx, exec } = fixture()
  await assert.rejects(
    () => runGlob(ctx, CAPS, { pattern: '*.ts', path: 'no-such-dir' }, exec),
    (error) => error instanceof SearchError && error.code === 'SEARCH_FAILED'
  )
})

// ---------- runGrep ----------

test('grep: finds matches incl. hidden/node_modules, skips binary and .git', async () => {
  const { ctx, exec } = fixture()
  const { matches } = await runGrep(ctx, CAPS, { pattern: 'TODO' }, exec)
  assert.deepEqual(matches.map((m) => m.path).sort(), ['.hidden.log', 'a.ts', 'node_modules/x/index.js', 'sub/a.txt'])
})

test('grep: line numbers are 1-based', async () => {
  const { ctx, exec } = fixture()
  const { matches } = await runGrep(ctx, CAPS, { pattern: 'TODO' }, exec)
  assert.equal(matches.find((m) => m.path === 'a.ts').lineNumber, 2)
})

test('grep: CR is stripped from matched lines', async () => {
  const { ctx, exec } = fixture()
  const { matches } = await runGrep(ctx, CAPS, { pattern: 'hello' }, exec)
  assert.equal(matches.length, 1)
  assert.equal(matches[0].line.includes('\r'), false)
})

test('grep: include filter narrows candidates', async () => {
  const { ctx, exec } = fixture()
  const { matches } = await runGrep(ctx, CAPS, { pattern: 'export const', include: '*.ts' }, exec)
  assert.equal(matches.length, 3)
})

test('grep: file target works, dir target with no match stays empty', async () => {
  const { ctx, exec } = fixture()
  assert.equal((await runGrep(ctx, CAPS, { pattern: 'hello', path: 'readme.md' }, exec)).matches.length, 1)
  assert.equal((await runGrep(ctx, CAPS, { pattern: 'world', path: 'src' }, exec)).matches.length, 0)
})

test('grep: invalid regex fails with SEARCH_INVALID_PATTERN', async () => {
  const { ctx, exec } = fixture()
  await assert.rejects(
    () => runGrep(ctx, CAPS, { pattern: '(unclosed' }, exec),
    (error) => error instanceof SearchError && error.code === 'SEARCH_INVALID_PATTERN'
  )
})

test('grep: content pattern compiles case-sensitively by default', () => {
  assert.equal(compileContentPattern('grep', 'TODO').test('todo'), false)
  assert.equal(compileContentPattern('grep', 'TODO').test('a TODO b'), true)
})

// ---------- retention & render ----------

test('retention: caps match count and line bytes', () => {
  const matches = [
    { path: 'a', lineNumber: 1, line: 'x'.repeat(5000) },
    { path: 'b', lineNumber: 2, line: 'y' },
    { path: 'c', lineNumber: 3, line: 'z' }
  ]
  const retained = retainGrepMatches(matches, 2, 2000)
  assert.equal(retained.length, 2)
  assert.ok(Buffer.byteLength(retained[0].line, 'utf8') <= 2000)
})

test('render: header shows partial counts and footer advises narrowing', () => {
  const matches = [
    { path: 'a', lineNumber: 1, line: 'x' },
    { path: 'b', lineNumber: 2, line: 'y' },
    { path: 'c', lineNumber: 3, line: 'z' }
  ]
  const partial = formatRetainedGrep(retainGrepMatches(matches, 2, 2000), matches.length)
  assert.ok(partial.startsWith('Found 2 of 3 matches'))
  assert.ok(partial.includes('narrow pattern, path, or include'))
  const exact = formatRetainedGrep(retainGrepMatches(matches, 250, 2000), matches.length)
  assert.ok(exact.startsWith('Found 3 matches'))
})

test('render: no-match text', () => {
  assert.equal(formatRetainedGrep([], 0), 'No matches found')
})

test('render: matches group by file with line numbers', () => {
  const text = formatGrepMatches([
    { path: 'a.ts', lineNumber: 2, line: 'TODO x' },
    { path: 'a.ts', lineNumber: 5, line: 'TODO y' },
    { path: 'b.ts', lineNumber: 1, line: 'TODO z' }
  ])
  assert.ok(text.includes('a.ts'))
  assert.ok(text.includes('Line 2: TODO x'))
  assert.ok(text.includes('b.ts'))
})

test('render: glob page footer reports the cut', () => {
  const page = formatGlobPage(['p1', 'p2'], 500)
  assert.ok(page.includes('Showing 2 of 500 paths'))
})

test('previewLine: caps bytes UTF-8-safely and marks truncation', () => {
  const longLine = 'x'.repeat(5000)
  const preview = previewLine(longLine, 2000)
  assert.ok(Buffer.byteLength(preview, 'utf8') <= 2000)
  assert.ok(preview.endsWith('(line truncated)'))
  const cjk = '你'.repeat(1500)
  const cjkPreview = previewLine(cjk, 2000)
  assert.ok(Buffer.byteLength(cjkPreview, 'utf8') <= 2000)
  assert.ok(!cjkPreview.includes('\uFFFD'))
})

// ---------- arg parsing & helpers ----------

test('parseGlobArgs: defaults and path passthrough', () => {
  assert.deepEqual(parseGlobArgs({ pattern: '*.ts' }), { pattern: '*.ts' })
  assert.deepEqual(parseGlobArgs({ pattern: '*.ts', path: 'src' }), { pattern: '*.ts', path: 'src' })
})

test('parseGrepArgs: pattern, path, include', () => {
  assert.deepEqual(parseGrepArgs({ pattern: 'x' }), { pattern: 'x' })
  assert.deepEqual(parseGrepArgs({ pattern: 'x', include: '*.ts' }), { pattern: 'x', include: '*.ts' })
})

test('toWorkdirRelative: strips the workdir prefix', () => {
  const ws = '/tmp/ws'
  assert.equal(toWorkdirRelative(`${ws}/src/a.ts`, ws), 'src/a.ts')
  assert.equal(toWorkdirRelative('already/relative.ts', ws), 'already/relative.ts')
})

// ---------- containment variants beyond contain.test.mjs ----------

test('containment: normalized escape (src/../..) is rejected', async () => {
  const { ctx, exec } = fixture()
  await assert.rejects(
    () => runGlob(ctx, CAPS, { pattern: '*.ts', path: 'src/../..' }, exec),
    /escapes the session workspace/
  )
})

test('containment: workdir itself and ./sub stay allowed', async () => {
  const { ctx, exec } = fixture()
  assert.equal((await runGlob(ctx, CAPS, { pattern: '*.ts', path: '.' }, exec)).paths.length, 3)
  assert.equal((await runGlob(ctx, CAPS, { pattern: '*.ts', path: './src' }, exec)).paths.length, 2)
})
